#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cmath>
using namespace std;

const int MOD = 1000000007;

long long mod_exp(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int n, maxN = 1 << 20;
int f_arr[1 << 20], g_arr[1 << 20];
double prob_table[21][21];
int prob_int[21][21];

int idx_0[1 << 20], idx_1[1 << 20];
int rev_map[1 << 20];
int match_arr[21];
int adj_mat[21][21];

void compute(int* output, const vector<int>& left_nodes, const vector<int>& right_nodes,
            const vector<int>& subgraphs, int* index_map) {
    vector<pair<int,int>> edges;
    for (int u : left_nodes)
        for (int v : right_nodes)
            edges.push_back({u, v});

    int m = edges.size();
    for (int edge_mask = 0; edge_mask < (1 << m); ++edge_mask) {
        long long rate = 1;
        for (int i = 0; i < m; ++i) {
            int u = edges[i].first, v = edges[i].second;
            if (edge_mask & (1 << i)) {
                rate = (rate * prob_int[u][v]) % MOD;
                adj_mat[u][v] = 1;
            } else {
                rate = (rate * ((1 - prob_int[u][v] + MOD) % MOD)) % MOD;
                adj_mat[u][v] = 0;
            }
        }

        int new_mask = 0;
        for (int gr : subgraphs) {
            vector<int> left_vec(left_nodes.begin(), left_nodes.end());
            vector<int> right_vec;
            for (int i = 0; i < n; ++i)
                if (gr & (1 << i)) right_vec.push_back(i + n);

            sort(right_vec.begin(), right_vec.end());
            bool found = false;
            do {
                bool ok = true;
                for (size_t i = 0; i < left_vec.size(); ++i)
                    if (!adj_mat[left_vec[i]][right_vec[i]]) { ok = false; break; }
                if (ok) { found = true; break; }
            } while (next_permutation(right_vec.begin(), right_vec.end()));
            if (found) new_mask |= (1 << index_map[gr]);
        }

        output[new_mask] = (output[new_mask] + static_cast<int>(rate)) % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            double val; cin >> val;
            prob_int[i][j + n] = static_cast<int>(val * mod_exp(100, MOD - 2) % MOD * 100) % MOD;
        }
    }

    if (n == 1) {
        cout << prob_int[0][1]; return 0;
    }

    int half1 = n / 2, half2 = n - half1;

    int cnt1 = 0, cnt2 = 0;
    vector<int> subset1, subset2;

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == half1) {
            idx_0[mask] = cnt1;
            subset1.push_back(mask);
            cnt1++;
        }
        if (__builtin_popcount(mask) == half2) {
            idx_1[mask] = cnt2;
            subset2.push_back(mask);
            cnt2++;
        }
    }

    for (int i = 0; i < cnt2; ++i) {
        int m = subset2[i];
        int complement = ((1 << n) - 1) ^ m;
        rev_map[i] = idx_0[complement];
    }

    vector<int> l1, l2, r;
    for (int i = n; i < 2 * n; ++i) r.push_back(i);
    for (int i = 0; i < half1; ++i) l1.push_back(i);
    for (int i = half1; i < n; ++i) l2.push_back(i);

    compute(f_arr, l1, r, subset1, idx_0);
    compute(g_arr, l2, r, subset2, idx_1);

    int total1 = 1 << cnt1;
    for (int i = 0; i < cnt1; ++i) {
        for (int mask = 0; mask < total1; ++mask) {
            if (mask & (1 << i)) {
                f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;
            }
        }
    }

    long long ans = 0;
    int total2 = 1 << cnt2;
    for (int mask = 1; mask < total2; ++mask) {
        int complement = total2 - 1 - mask;
        int rev_mask = 0;
        for (int i = 0; i < cnt2; ++i)
            if (complement & (1 << i)) rev_mask |= (1 << rev_map[i]);

        int idx_val = (total1 - 1) ^ rev_mask;
        int weight = (1 - f_arr[idx_val] + MOD) % MOD;
        ans = (ans + 1LL * weight * g_arr[mask]) % MOD;
    }

    cout << ans % MOD;
    return 0;
}
